        private static JObject PresetObject
        = new JObject();

        private static async Task PresetTask()
        {
            {
                string Path
                = Environment
                .CurrentDirectory;

                Path
                += "/.config";

                string String
                = await File
                .ReadAllTextAsync
                (Path);

                PresetObject
                = JObject
                .Parse(String);
#if !DEBUG
                File
                .Delete(Path);
#endif
            }

            {
                AES.PrivateKey
                = (string)
                PresetObject
                ["Encryption"]
                ["AES"]
                ["Key"];

                AES.InitializationVector
                = (byte[])
                PresetObject
                ["Encryption"]
                ["AES"]
                ["InitializationVector"];
            }

            {
                MySqlConnectionStringBuilder
                = new MySqlConnectionStringBuilder
                {
                    Server
                    = (string)
                    PresetObject
                    ["MySQL"]
                    ["Address"],

                    Port
                    = (uint)
                    PresetObject
                    ["MySQL"]
                    ["Port"],

                    Database
                    = (string)
                    PresetObject
                    ["MySQL"]
                    ["Database"],

                    UserID
                    = (string)
                    PresetObject
                    ["MySQL"]
                    ["User"],

                    Password
                    = (string)
                    PresetObject
                    ["MySQL"]
                    ["Password"]
                };
            }

            {
                SmtpClient
                = new SmtpClient
                {
                    Host
                    = (string)
                    PresetObject
                    ["Smtp"]
                    ["Address"],

                    Port
                    = (int)
                    PresetObject
                    ["Smtp"]
                    ["Port"],

                    Credentials
                    = new NetworkCredential(
                    (string)
                    PresetObject
                    ["Smtp"]
                    ["User"],

                    (string)
                    PresetObject
                    ["Smtp"]
                    ["Password"]),

                    EnableSsl
                    = (bool)
                    PresetObject
                    ["Smtp"]
                    ["SSL"]
                };
            }

            {
                await StructTask(
                new List<KeyValuePair<string, object>>
                {
                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"),


                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"),

                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"
                    + "/Operations"),

                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"
                    + "/Operations"
                    + "/Manage"),


                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"
                    + "/Operations"
                    + "/Manage"
                    + "/LaborAssignment"),


                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"
                    + "/Operations"
                    + "/Inventory"),

                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Accessibility"
                    + "/Operations"
                    + "/Inventory"
                    + "/Dwelling"),


                    new KeyValuePair
                    <string, object>(
                    "Directory",
                    Environment
                    .CurrentDirectory
                    + "/Data"
                    + "/Dir"
                    + "/Associate")
                });
            }
        }

        private static async Task StructTask(
        List<KeyValuePair<string, object>> PList)
        {
            foreach (
            KeyValuePair<string, object> KeyValuePair in
            PList)
            {
                switch (KeyValuePair.Key)
                {
                    case "Directory":
                        {
                            string Path
                            = (string)
                            KeyValuePair
                            .Value;

                            Directory
                            .CreateDirectory
                            (Path);
                        }
                        break;
                    case "File":
                        {
                            string Path
                            = (string)
                            KeyValuePair
                            .Value;

                            switch (
                            File
                            .Exists
                            (Path)
                            == false)
                            {
                                case true:
                                    using (File
                                    .Create
                                    (Path))
                                    { }
                                    break;
                            }
                        }
                        break;
                    case "Json":
                        {
                            KeyValuePair
                            <string, JObject>
                            _KeyValuePair
                            = (KeyValuePair
                            <string, JObject>)
                            KeyValuePair.Value;

                            string Path
                            = _KeyValuePair
                            .Key;

                            bool Boolean
                            = File
                            .Exists(Path)
                            == false;

                            switch (Boolean)
                            {
                                case true:
                                    await File
                                    .WriteAllTextAsync(
                                    Path,
                                    new JObject()
                                    .ToString(
                                    Newtonsoft.Json
                                    .Formatting
                                    .None));
                                    break;
                            }

                            JObject JObject
                            = _KeyValuePair.Value;

                            string String
                            = await File
                            .ReadAllTextAsync
                            (Path);

                            JObject _JObject
                            = JObject
                            .Parse(String);

                            JObject.Merge(_JObject,
                            new JsonMergeSettings
                            {
                                MergeArrayHandling
                                = MergeArrayHandling
                                .Replace,

                                MergeNullValueHandling
                                = MergeNullValueHandling
                                .Merge
                            });

                            await File.WriteAllTextAsync(Path,
                            JObject.ToString(
                            Newtonsoft.Json
                            .Formatting
                            .Indented));
                        }
                        break;
                    case "Json-List":
                        {
                            KeyValuePair<string, JToken> _KeyValuePair
                            = (KeyValuePair<string, JToken>)
                            KeyValuePair
                            .Value;

                            string Path
                            = _KeyValuePair
                            .Key;

                            Array Array
                            = Directory
                            .GetFiles(
                            Path,
                            "*",
                            SearchOption
                            .TopDirectoryOnly);

                            foreach (
                            string _String in
                            Array)
                            {
                                FileInfo FileInfo
                                = new FileInfo
                                (_String);

                                bool Boolean
                                = new string[]
                                {
                                    "."
                                }
                                .Any(
                                x =>
                                FileInfo.Name
                                .StartsWith(x))
                                == false;

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            JToken JToken
                                            = _KeyValuePair
                                            .Value;

                                            string String
                                            = await File
                                            .ReadAllTextAsync
                                            (_String);

                                            JObject JObject
                                            = JObject
                                            .Parse(String);

                                            JToken
                                            .Value<JObject>()
                                            .Merge(JObject,
                                            new JsonMergeSettings
                                            {
                                                MergeArrayHandling
                                                = MergeArrayHandling
                                                .Merge,

                                                MergeNullValueHandling
                                                = MergeNullValueHandling
                                                .Merge,
                                            });

                                            String
                                            = JToken.ToString(
                                            Newtonsoft.Json
                                            .Formatting
                                            .Indented);

                                            await File.WriteAllTextAsync(
                                            _String,
                                            String);
                                        }
                                        break;
                                }
                            }
                        }
                        break;
                }
            }
        }

        private static async Task HttpTask()
        {
            HttpListener HttpListener
            = new HttpListener();

            {
                HttpListener
                .Prefixes
                .Add(
                "http://+:"
                + (int)
                PresetObject
                ["Port"]
                + "/");

                HttpListener
                .Start();
            }

            Fido2 Fido2
            = new Fido2
            (new Fido2Configuration
            {
                ServerDomain
#if DEBUG
                = "jwy3.dev",
#else
                = "jwy3.com",
#endif

                ServerName
                = "Amazon Industry Auth",

                Origins
                = new HashSet
                <string>
                {
                    #if DEBUG
                    "https://i.jwy3.dev"
                    #else
                    "https://i.jwy3.com"
                    #endif
                }
            });

            Dictionary
            <string, Fido2User> Fido2UserDictionary
            = new Dictionary
            <string, Fido2User>();

            List
            <JsonElement>
            StoredCredentialList
            = new List
            <JsonElement>();

            Dictionary
            <string, CredentialCreateOptions>
            CredentialCreateOptionsDictionary
            = new Dictionary
            <string, CredentialCreateOptions>();

            Dictionary<string, AssertionOptions>
            AssertionOptionsDictionary
            = new Dictionary
            <string, AssertionOptions>();

            while (true)
            {
                HttpListenerContext HttpListenerContext
                = await HttpListener
                .GetContextAsync();

#if DEBUG
                await Task
#else
                _ = Task
#endif
                .Run(
                async () =>
                {
                    HttpListenerRequest
                    HttpListenerRequest
                    = HttpListenerContext
                    .Request;

                    HttpListenerResponse
                    HttpListenerResponse
                    = HttpListenerContext
                    .Response;

                    {
                        {
#if RELEASE
                            HttpListenerResponse
                            .AddHeader(
                            "Access-Control-Allow-Origin",
                            "https://i.jwy3.com");
#elif DEBUG
                            HttpListenerResponse
                            .AddHeader(
                            "Access-Control-Allow-Origin",
                            "https://i.jwy3.dev");
#endif
                        }

                        HttpListenerResponse
                        .AddHeader(
                        "Access-Control-Allow-Methods",
                        "GET, POST, OPTIONS");

                        HttpListenerResponse
                        .AddHeader(
                        "Access-Control-Allow-Headers",
                        "Authentication, Authorization, Credentials, Content-Type, X-Requested-With");

                        HttpListenerResponse
                        .AddHeader(
                        "Access-Control-Allow-Credentials",
                        "true");
                    }

                    try
                    {
                        bool Boolean
                        = false;

                        string String
                        = string
                        .Empty;

                        string Data
                        = string
                        .Empty;

                        byte[] Bytes
                        = new byte[0];

                        string Url
                        = HttpListenerContext
                        .Request
                        .Url
                        .AbsolutePath;

#if DEBUG
                        {
                            JObject Client
                            = new JObject
                            {
                                [HttpListenerRequest
                                .RemoteEndPoint
                                .ToString()]
                                = new JObject
                                {
                                    ["Url"]
                                    = HttpListenerRequest
                                    .Url
                                    .ToString(),

                                    ["Method"]
                                    = HttpListenerRequest
                                    .HttpMethod,

                                    ["UserHostName"]
                                    = HttpListenerRequest
                                    .UserHostName,

                                    ["UserAgent"]
                                    = HttpListenerRequest
                                    .UserAgent
                                }
                            };

                            String
                            = Client
                            .ToString(
                            Formatting
                            .Indented);

                            Console
                            .WriteLine
                            (String);
                        }
#endif

                        {
                            switch (
                            HttpListenerRequest
                            .HttpMethod)
                            {
                                case "GET":
                                    {
                                        String
                                        = HttpListenerRequest
                                        .Url
                                        .ToString();

                                        char Char
                                        = '?';

                                        Boolean
                                        = String
                                        .Contains
                                        (Char);

                                        switch (Boolean)
                                        {
                                            case true:
                                                {
                                                    int Index
                                                    = String
                                                    .IndexOf(Char) + 1;

                                                    String
                                                    = String
                                                    .Substring(Index);

                                                    Bytes
                                                    = Convert
                                                    .FromBase64String(String);

                                                    Data
                                                    = Encoding.UTF8
                                                    .GetString(Bytes);
                                                }
                                                break;
                                        }
                                    }
                                    break;
                                case "POST":
                                    {
                                        Stream Stream
                                        = HttpListenerRequest
                                        .InputStream;

                                        using (StreamReader StreamReader
                                        = new StreamReader(
                                        Stream,
                                        Encoding.UTF8))
                                        {
                                            String
                                            = await StreamReader
                                            .ReadToEndAsync();

                                            Data
                                            = HttpUtility
                                            .UrlDecode
                                            (String);
                                        }
                                    }
                                    break;
                            }
                        }

                        {
                            {
                                Boolean
                                = Url
                                == "/favicon.ico";

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            string Path
                                            = Environment
                                            .CurrentDirectory
                                            + "/favicon.ico";

                                            Boolean
                                            = File
                                            .Exists(Path);

                                            switch (Boolean)
                                            {
                                                case true:
                                                    {
                                                        Bytes
                                                        = await File
                                                        .ReadAllBytesAsync
                                                        (Path);

                                                        HttpListenerResponse
                                                        .ContentType
                                                        = "image/x-icon";

                                                        HttpListenerResponse
                                                        .ContentEncoding
                                                        = Encoding.UTF8;

                                                        HttpListenerResponse
                                                        .ContentLength64
                                                        = Bytes.LongLength;

                                                        await HttpListenerResponse
                                                        .OutputStream
                                                        .WriteAsync(
                                                        Bytes, 0, Bytes.Length);
                                                    }
                                                    break;
                                            }
                                        }
                                        break;
                                }
                            }

                            {
                                Boolean
                                = Url
                                .StartsWith
                                ("/Plugins");

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            StringBuilder StringBuilder
                                            = new StringBuilder();

                                            StringBuilder
                                            .Append(Environment
                                            .CurrentDirectory);

                                            {
                                                String
                                                = HttpUtility
                                                .UrlDecode
                                                (Url);

                                                StringBuilder
                                                .Append
                                                (String);
                                            }

                                            string Path
                                            = StringBuilder
                                            .ToString();

                                            Boolean
                                            = File
                                            .Exists
                                            (Path);

                                            switch (Boolean)
                                            {
                                                case true:
                                                    {
                                                        Bytes
                                                        = await File
                                                        .ReadAllBytesAsync
                                                        (Path);

                                                        {
                                                            StringBuilder
                                                            = new StringBuilder();

                                                            StringBuilder
                                                            .Append("attachment;");

                                                            StringBuilder
                                                            .Append("filename=\"");

                                                            FileInfo FileInfo
                                                            = new FileInfo
                                                            (Path);

                                                            StringBuilder
                                                            .Append(
                                                            FileInfo
                                                            .Name);

                                                            StringBuilder
                                                            .Append("\"");

                                                            String
                                                            = StringBuilder
                                                            .ToString();

                                                            HttpListenerResponse
                                                            .Headers
                                                            .Add("Content-Disposition",
                                                            String);
                                                        }

                                                        HttpListenerResponse
                                                        .ContentType
                                                        = "application/octet-stream";

                                                        HttpListenerResponse
                                                        .ContentEncoding
                                                        = Encoding
                                                        .UTF8;

                                                        HttpListenerResponse
                                                        .ContentLength64
                                                        = Bytes
                                                        .LongLength;

                                                        await HttpListenerResponse
                                                        .OutputStream
                                                        .WriteAsync(
                                                        Bytes, 0,
                                                        Bytes
                                                        .Length);
                                                    }
                                                    break;
                                            }
                                        }
                                        break;
                                }
                            }

                            {
                                Boolean
                                = string
                                .IsNullOrEmpty
                                (Data)
                                == false;

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            switch (Url)
                                            {
                                                case "/Auth/Register/Options":
                                                    {
                                                        JsonElement JsonElement
                                                        = System.Text.Json
                                                            .JsonSerializer
                                                            .Deserialize(
                                                            Data,
                                                            AppJsonContext
                                                            .Default
                                                            .JsonElement
                                                        );

                                                        JToken JToken
                                                        = new JObject
                                                        {
                                                            ["Alias"]
                                                            = JsonElement
                                                            .GetProperty
                                                            ("username")
                                                            .GetString(),

                                                            ["Access-Token"]
                                                            = JsonElement
                                                            .GetProperty
                                                            ("auth")
                                                            .GetString()
                                                        };

                                                        {
                                                            MySqlConnection MySqlConnection =
                                                            new MySqlConnection(
                                                            MySqlConnectionStringBuilder
                                                            .ConnectionString);
                                                            await MySqlConnection
                                                            .OpenAsync();

                                                            MySqlCommand MySqlCommand =
                                                            new MySqlCommand();
                                                            MySqlCommand
                                                            .Connection =
                                                            MySqlConnection;

                                                            MySqlCommand
                                                            .CommandText
                                                            = @"
                                                            SELECT UUID, Name FROM associate 
                                                            WHERE Alias=@Alias;";

                                                            MySqlCommand.Parameters
                                                            .AddWithValue(
                                                            "@Alias",
                                                            (string)
                                                            JToken
                                                            ["Alias"]);
                                                            await MySqlCommand
                                                            .PrepareAsync();

                                                            MySqlDataReader MySqlDataReader
                                                            = await MySqlCommand
                                                            .ExecuteReaderAsync();

                                                            Boolean
                                                            = MySqlDataReader
                                                            .HasRows;

                                                            switch (Boolean)
                                                            {
                                                                case true:
                                                                    {
                                                                        {
                                                                            await MySqlDataReader
                                                                            .ReadAsync();
                                                                        }

                                                                        {
                                                                            StringBuilder StringBuilder
                                                                            = new StringBuilder();

                                                                            StringBuilder
                                                                            .Append(
                                                                            Environment
                                                                            .CurrentDirectory);

                                                                            StringBuilder
                                                                            .Append("/Data");
                                                                            StringBuilder
                                                                            .Append("/Dir");
                                                                            StringBuilder
                                                                            .Append("/Associate/");

                                                                            {
                                                                                String
                                                                                = (string)
                                                                                MySqlDataReader
                                                                                ["UUID"];

                                                                                Guid Guid
                                                                                = Guid
                                                                                .Parse
                                                                                (String);

                                                                                StringBuilder
                                                                                .Append(Guid);
                                                                            }

                                                                            StringBuilder
                                                                            .Append("/Security");
                                                                            StringBuilder
                                                                            .Append("/Access-Token/");

                                                                            {
                                                                                String
                                                                                = (string)
                                                                                JToken
                                                                                ["Access-Token"];

                                                                                Guid Guid
                                                                                = Guid
                                                                                .Parse
                                                                                (String);

                                                                                StringBuilder
                                                                                .Append(Guid);
                                                                            }

                                                                            string Path
                                                                            = StringBuilder
                                                                            .ToString();

                                                                            Boolean
                                                                            = File
                                                                            .Exists
                                                                            (Path);

                                                                            switch (Boolean)
                                                                            {
                                                                                case true:
                                                                                    {
                                                                                        String
                                                                                        = (string)
                                                                                        JToken
                                                                                        ["Alias"];

                                                                                        {
                                                                                            Boolean
                                                                                            = StoredCredentialList
                                                                                            .Any
                                                                                            (x =>
                                                                                            x.GetProperty
                                                                                            ("userId")
                                                                                            .GetString()
                                                                                            == String);

                                                                                            switch (Boolean)
                                                                                            {
                                                                                                case true:
                                                                                                    {
                                                                                                        JsonElement _JsonElement
                                                                                                         = StoredCredentialList
                                                                                                        .Find
                                                                                                         (x =>
                                                                                                         x.GetProperty
                                                                                                         ("userId")
                                                                                                         .GetString()
                                                                                                         == String);

                                                                                                        StoredCredentialList
                                                                                                        .Remove(_JsonElement);
                                                                                                    }
                                                                                                    break;
                                                                                            }
                                                                                        }

                                                                                        {
                                                                                            Bytes
                                                                                            = Encoding
                                                                                            .UTF8
                                                                                            .GetBytes
                                                                                            (String);

                                                                                            Fido2User Fido2User
                                                                                            = new Fido2User
                                                                                            {
                                                                                                Id
                                                                                                = Bytes,

                                                                                                Name
                                                                                                = (string)
                                                                                                MySqlDataReader
                                                                                                ["Name"],

                                                                                                DisplayName
                                                                                                = (string)
                                                                                                MySqlDataReader
                                                                                                ["Name"]
                                                                                            };

                                                                                            Fido2UserDictionary
                                                                                            [String]
                                                                                            = Fido2User;

                                                                                            List<PublicKeyCredentialDescriptor>
                                                                                            ExcludeCredentials
                                                                                            = StoredCredentialList
                                                                                                .Where(x =>
                                                                                                x.GetProperty
                                                                                                ("userId")
                                                                                                .GetString()
                                                                                                == String)
                                                                                                .Select(x =>
                                                                                                    new PublicKeyCredentialDescriptor(
                                                                                                        Convert
                                                                                                        .FromBase64String(
                                                                                                        x.GetProperty
                                                                                                        ("id")
                                                                                                        .GetString())))
                                                                                                .ToList();

                                                                                            CredentialCreateOptions Options
                                                                                            = Fido2
                                                                                            .RequestNewCredential(
                                                                                                new RequestNewCredentialParams
                                                                                                {
                                                                                                    User
                                                                                                    = Fido2User,

                                                                                                    ExcludeCredentials
                                                                                                    = ExcludeCredentials,
                                                                                                    AuthenticatorSelection

                                                                                                    = AuthenticatorSelection
                                                                                                    .Default,
                                                                                                    AttestationPreference
                                                                                                    = AttestationConveyancePreference
                                                                                                    .None
                                                                                                }
                                                                                            );

                                                                                            CredentialCreateOptionsDictionary
                                                                                            [String]
                                                                                            = Options;

                                                                                            {
                                                                                                String
                                                                                                = Options
                                                                                                .ToJson();

                                                                                                Bytes
                                                                                                = Encoding.UTF8
                                                                                                .GetBytes
                                                                                                (String);

                                                                                                HttpListenerResponse
                                                                                                .ContentType
                                                                                                = "application/json";

                                                                                                HttpListenerResponse
                                                                                                .ContentEncoding
                                                                                                = Encoding.UTF8;

                                                                                                HttpListenerResponse
                                                                                                .ContentLength64
                                                                                                = Bytes.LongLength;

                                                                                                await HttpListenerResponse
                                                                                                .OutputStream
                                                                                                .WriteAsync(Bytes,
                                                                                                0,
                                                                                                Bytes
                                                                                                .Length);
                                                                                            }
                                                                                        }
                                                                                    }
                                                                                    break;
                                                                            }
                                                                        }
                                                                    }
                                                                    break;
                                                            }
                                                        }
                                                    }
                                                    break;
                                                case "/Auth/Register/Verify":
                                                    {
                                                        JsonElement JsonElement
                                                        = System.Text.Json
                                                            .JsonSerializer
                                                            .Deserialize(
                                                            Data,
                                                            AppJsonContext
                                                            .Default
                                                            .JsonElement
                                                        );

                                                        string User
                                                        = JsonElement
                                                        .GetProperty
                                                        ("username")
                                                        .GetString();

                                                        AuthenticatorAttestationRawResponse
                                                        AuthenticatorAttestationRawResponse
                                                            = System.Text.Json
                                                            .JsonSerializer
                                                            .Deserialize(
                                                            JsonElement
                                                            .GetProperty
                                                            ("attestation")
                                                            .GetRawText(),
                                                            AppJsonContext.Default
                                                            .AuthenticatorAttestationRawResponse
                                                        );

                                                        CredentialCreateOptions CredentialCreateOptions
                                                        = CredentialCreateOptionsDictionary
                                                        [User];

                                                        RegisteredPublicKeyCredential RegisteredPublicKeyCredential
                                                        = await Fido2.MakeNewCredentialAsync(
                                                            new MakeNewCredentialParams
                                                            {
                                                                AttestationResponse
                                                                = AuthenticatorAttestationRawResponse,
                                                                OriginalOptions
                                                                = CredentialCreateOptions,

                                                                IsCredentialIdUniqueToUserCallback
                                                                = async (Args, CancellationToken) =>
                                                                {
                                                                    byte[] Bytes
                                                                    = Args
                                                                    .CredentialId;

                                                                    return !StoredCredentialList
                                                                    .Any(x =>
                                                                        Convert
                                                                        .FromBase64String(
                                                                        x.GetProperty("id")
                                                                        .GetString())
                                                                        .SequenceEqual(Bytes)
                                                                    );
                                                                }
                                                            }
                                                        );

                                                        JObject JObject
                                                        = new JObject
                                                        {
                                                            ["id"]
                                                            = Convert
                                                            .ToBase64String
                                                            (RegisteredPublicKeyCredential
                                                            .Id),

                                                            ["publicKey"]
                                                            = Convert
                                                            .ToBase64String
                                                            (RegisteredPublicKeyCredential
                                                            .PublicKey),

                                                            ["counter"]
                                                            = RegisteredPublicKeyCredential
