                                                ["UUID"]);

                                                StringBuilder
                                                .Append("/Photo");
                                                StringBuilder
                                                .Append("/Picture");
                                                StringBuilder
                                                .Append(".jpg");

                                                Path
                                                = StringBuilder
                                                .ToString();

                                                {
