                                                                + "_");

                                                                StringBuilder
                                                                .Append(Width);
                                                                StringBuilder
                                                                .Append("x");
                                                                StringBuilder
                                                                .Append(Height);
                                                                StringBuilder
                                                                .Append(".jpg");

                                                                String
                                                                = StringBuilder
                                                                .ToString();

                                                                Boolean
                                                                = File
