                                                                        }
                                                                        break;
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }

                                            {
                                                StringBuilder StringBuilder
                                                = new StringBuilder();

                                                StringBuilder
                                                .Append(
                                                Environment
                                                .CurrentDirectory);

                                                StringBuilder
                                                .Append("/Data");
                                                StringBuilder
                                                .Append("/Dir");
                                                StringBuilder
                                                .Append("/Associate/");

                                                StringBuilder
                                                .Append(
                                                (string)
                                                Dictionary
                                                ["UUID"]);

                                                StringBuilder
                                                .Append("/Accessibility");

                                                Path
                                                = StringBuilder
                                                .ToString();

                                                await StructTask(
                                                new List<KeyValuePair
                                                <string, object>>
                                                {
                                                    new KeyValuePair
                                                    <string, object>(
                                                    "Json-List",
                                                    new KeyValuePair
                                                    <string, JToken>(
                                                    Path,
                                                    new JObject
                                                    {
                                                        ["Time"]
                                                        = DateTime
                                                        .UtcNow,

