                                }
                            }

                            {
                                Path
                                = "Associate"
                                + ".Security"
                                + ".Access-Token";

                                JToken
                                = PJToken
                                .SelectToken
                                (Path);

                                Boolean
                                = JToken
                                != null;

                                switch (Boolean)
                                {
                                    case true:
                                        {
                                            string String
                                            = (string)
                                            Dictionary
                                            ["UUID"];

                                            Guid Guid
                                            = Guid
                                            .Parse
                                            (String);

                                            {
                                                {
                                                    StringBuilder StringBuilder
                                                    = new StringBuilder();

                                                    StringBuilder
                                                    .Append(
                                                    Environment
                                                    .CurrentDirectory);

                                                    StringBuilder
                                                    .Append(
                                                    "/Data/Dir/Associate/");

                                                    StringBuilder
                                                    .Append(
                                                    Guid);

                                                    StringBuilder
                                                    .Append(
                                                    "/Security/Access-Token/");

                                                    Path
                                                    = StringBuilder
                                                    .ToString();
                                                }

                                                {
                                                    Boolean
                                                    = true;

                                                    while (Boolean)
                                                    {
                                                        Guid
                                                        = Guid
                                                        .NewGuid();

                                                        Boolean
                                                        = File
                                                        .Exists(
                                                        Path
                                                        + Guid);

                                                        await
                                                        Task
                                                        .Delay(
                                                        TimeSpan
                                                        .FromSeconds(2));
                                                    }
                                                }

                                                DateTime DateTime
                                                = DateTime
                                                .UtcNow
                                                .AddHours(12);

                                                {
                                                    Path
                                                    += Guid;

                                                    JObject JObject
                                                    = new JObject
                                                    {
                                                        ["Time"]
                                                        = DateTime
                                                    };

                                                    String
                                                    = JObject
                                                    .ToString(
                                                    Formatting
                                                    .Indented);

                                                    await File
                                                    .WriteAllTextAsync(
                                                    Path,
                                                    String);
                                                }

                                                {
                                                    JToken
                                                    = new JObject
                                                    {
                                                        ["UUID"]
                                                        = (string)
                                                        Dictionary
                                                        ["UUID"],

                                                        ["Access-Token"]
                                                        = Guid,

                                                        ["Time"]
                                                        = DateTime
                                                    };
                                                }
                                            }
                                        }
                                        break;
                                }
                            }
                        }
                        break;
                }
            }

            return
            JToken;
        }

        private static async Task SchedulerTask()
        {
            List<KeyValuePair<
                KeyValuePair
                    <TimeSpan,
                    DateTime>,
                Action>> List
            = new List<KeyValuePair
                <KeyValuePair
                    <TimeSpan,
                    DateTime>,
            Action>>
            {
                // Scheduler for 
                // Accessibility
                // .Operations
                // .Inventory
                // .Dwelling

                new KeyValuePair
                <KeyValuePair
                <TimeSpan,
                DateTime>,
                Action>(
                new KeyValuePair
                <TimeSpan,
                DateTime>(
                TimeSpan
                .FromDays(1),
                DateTime.Now),
                new Action(
                async () =>
                {

                    // Set-Up the  
                    // Location file
                    {
                        StringBuilder StringBuilder
                        = new StringBuilder();

                        StringBuilder
                        .Append(
                        Environment
                        .CurrentDirectory);

                        StringBuilder
                        .Append("/Data");
                        StringBuilder
                        .Append("/Dir");
                        StringBuilder
                        .Append("/Accessibility");
                        StringBuilder
                        .Append("/Operations");
                        StringBuilder
                        .Append("/Inventory");
                        StringBuilder
                        .Append("/Dwelling/");

                        string Path
                        = StringBuilder
                        .ToString();

                        Array Array
                        = Directory
                        .GetDirectories
                        (Path,
                        "*",
                        SearchOption
                        .TopDirectoryOnly);

                        foreach (string _String
                        in Array)
                        {
                            {
                                {
                                    StringBuilder
                                    = new StringBuilder();

                                    StringBuilder
                                    .Append(_String);

                                    StringBuilder
                                    .Append("/Visualization");

                                    Path
                                    = StringBuilder
                                    .ToString();
                                }

                                {
                                    string String
                                    = await File
                                    .ReadAllTextAsync
                                    (Path);

                                    JArray JArray
                                    = JArray
                                    .Parse(String);

                                    int Length
                                    = JArray
                                    .Count;

                                    for (int i = 0; i < Length; i++)
                                    {
                                        JToken JToken
                                        = JArray
                                        .ElementAt(i);

                                        {
                                            {
                                                StringBuilder
                                                = new StringBuilder();

                                                StringBuilder
                                                .Append(_String);

                                                StringBuilder
                                                .Append("/Location");

                                                Path
                                                = StringBuilder
                                                .ToString();
                                            }

                                            {
                                                StringBuilder
                                                = new StringBuilder();

                                                {
                                                    String
                                                    = (string)
                                                    JToken
                                                    ["Addressable"];

                                                    StringBuilder
                                                    .Append(String);
                                                }

                                                StringBuilder
                                                .Append("-");

                                                {
                                                    String
                                                    = (string)
                                                    JToken
                                                    ["Label"];

                                                    int Index
                                                    =  String
                                                    .IndexOf(' ');

                                                    Index
                                                    ++;

                                                    String
                                                    = String
                                                    .Substring
                                                    (Index);

                                                    Index
                                                    = int
                                                    .Parse
                                                    (String);

                                                    String
                                                    = Index
                                                    .ToString
                                                    ("00");

                                                    StringBuilder
                                                    .Append(String);
                                                }
                                            }

                                            {
                                                using (FileStream FileStream
                                                = new FileStream(
                                                Path,
                                                FileMode.OpenOrCreate,
                                                FileAccess.ReadWrite,
                                                FileShare.Read))
                                                {
                                                    long Long
                                                    = FileStream
                                                    .Length;

                                                    byte[] Bytes
                                                    = new byte
                                                    [Long];

                                                    await FileStream
                                                    .ReadAsync
                                                    (Bytes);

                                                    {
                                                        String
                                                        = Encoding.UTF8
                                                        .GetString(Bytes);

                                                        Array _Array
                                                        = String
                                                        .Split(
                                                        new string[]
                                                        {
                                                            Environment
                                                            .NewLine
                                                        },
                                                        StringSplitOptions
                                                        .RemoveEmptyEntries);

                                                        List<string> List
                                                        = new List
                                                        <string>();

                                                        List
                                                        .AddRange(
                                                        (string[])
                                                        _Array);

                                                        {
                                                            String
                                                            = StringBuilder
                                                            .ToString();

                                                            bool Boolean
                                                            = List
                                                            .Contains
                                                            (String)
                                                            == false;

                                                            switch (Boolean)
                                                            {
                                                                case true:
                                                                    {
                                                                        List
                                                                        .Add
                                                                        (String);
                                                                    }
                                                                    break;
                                                            }
                                                        }

                                                        String
                                                        = String
                                                        .Join(
                                                        Environment
                                                        .NewLine,
                                                        List);
                                                    }

                                                    Bytes
                                                    = Encoding.UTF8
                                                    .GetBytes(String);

                                                    FileStream
                                                    .SetLength(0);

                                                    await FileStream
                                                    .WriteAsync(Bytes);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Remove dwelling inventory
                    // over past expiry date
                    {
                        StringBuilder StringBuilder
                        = new StringBuilder();

                        StringBuilder
                        .Append(
                        Environment
                        .CurrentDirectory);

                        StringBuilder
                        .Append("/Data");
                        StringBuilder
                        .Append("/Dir");
                        StringBuilder
                        .Append("/Accessibility");
                        StringBuilder
                        .Append("/Operations");
                        StringBuilder
                        .Append("/Inventory");
                        StringBuilder
                        .Append("/Dwelling/");

                        string Path
                        = StringBuilder
                        .ToString();

                        Array Array
                        = Directory
                        .GetDirectories
                        (Path,
                        "*",
                        SearchOption
                        .TopDirectoryOnly);

                        int Length
                        = Array
                        .Length;

                        for (int i = 0; i < Length; i++)
                        {
                            Path
                            = (string)
                            Array
                            .GetValue(i);

                            DirectoryInfo DirectoryInfo
                            = new DirectoryInfo(Path);

                            {
                                StringBuilder
                                = new StringBuilder();

                                {
                                    Path
                                    = DirectoryInfo
                                    .FullName;

                                    StringBuilder
                                    .Append(Path);
                                }

                                StringBuilder
                                .Append("/Container");

                                Path
                                = StringBuilder
                                .ToString();

                                {
                                    DirectoryInfo
                                    = new DirectoryInfo
                                    (Path);

                                    IReadOnlyCollection
                                    <DirectoryInfo>
                                    IReadOnlyCollection
                                    = DirectoryInfo
                                    .GetDirectories();

                                    for (int x = 0;
                                    x < IReadOnlyCollection
                                    .Count;
                                    x++)
                                    {
                                        DirectoryInfo
                                        = IReadOnlyCollection
                                        .ElementAt(x);

                                        {
                                           StringBuilder
                                            = new StringBuilder();

                                            {
                                                Path
                                                = DirectoryInfo
                                                .FullName;

                                                StringBuilder
                                                .Append(Path);
                                            }

                                            StringBuilder
                                            .Append("/Date");

                                            Path
                                            = StringBuilder
                                            .ToString();

                                            {
                                                string String
                                                = await File
                                                .ReadAllTextAsync
                                                (Path);

                                                DateTime DateTime
                                                = DateTime
                                                .Parse
                                                (String);

                                                bool Boolean
                                                = DateTime
                                                <= DateTime
                                                .UtcNow;

                                                switch (Boolean)
                                                {
                                                    case true:
                                                        {
                                                            MySqlConnection MySqlConnection
                                                            = new MySqlConnection(
                                                            MySqlConnectionStringBuilder
                                                            .ConnectionString);

                                                            await MySqlConnection
                                                            .OpenAsync();

                                                            MySqlCommand MySqlCommand
                                                            = new MySqlCommand();
                                                            MySqlCommand
                                                            .Connection
                                                            = MySqlConnection;

                                                            MySqlCommand
                                                            .CommandText
                                                            = @"DELETE 
                                                            FROM `ops-inv-dwell`
                                                            WHERE `ID` = @ID;";

                                                            {
                                                                String
                                                                = DirectoryInfo
                                                                .Name;

                                                                MySqlCommand
                                                                .Parameters
                                                                .AddWithValue(
                                                                "@ID",
                                                                String);
                                                            }

                                                            await MySqlCommand
                                                            .PrepareAsync();

                                                            int Index
                                                            = await MySqlCommand
                                                            .ExecuteNonQueryAsync();

                                                            Boolean
                                                            = Index
                                                            > 0;

                                                            switch (Boolean)
                                                            {
                                                                case true:
                                                                    {
                                                                        DirectoryInfo
                                                                        .Delete(true);
                                                                    }
                                                                    break;
                                                            }

                                                            await MySqlConnection
                                                            .CloseAsync();
                                                        }
                                                        break;
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    // Remove dwelling record files
                    {
                        StringBuilder StringBuilder
                        = new StringBuilder();

                        StringBuilder
                        .Append(
                        Environment
                        .CurrentDirectory);

                        StringBuilder
                        .Append("/Data");
                        StringBuilder
                        .Append("/Dir");
                        StringBuilder
                        .Append("/Accessibility");
                        StringBuilder
                        .Append("/Operations");
                        StringBuilder
                        .Append("/Inventory");
                        StringBuilder
                        .Append("/Dwelling/");

                        string Path
                        = StringBuilder
                        .ToString();

                        Array Array
                        = Directory
                        .GetDirectories
                        (Path,
                        "*",
                        SearchOption
                        .TopDirectoryOnly);

                        int Length
                        = Array
                        .Length;

                        for (int i = 0; i < Length; i++)
                        {
                            Path
                            = (string)
                            Array
                            .GetValue(i);

                            DirectoryInfo DirectoryInfo
                            = new DirectoryInfo(Path);

                            {
                                StringBuilder
                                = new StringBuilder();

                                {
                                    Path
                                    = DirectoryInfo
                                    .FullName;

                                    StringBuilder
                                    .Append(Path);
                                }

                                StringBuilder
                                .Append("/Records");

                                Path
                                = StringBuilder
                                .ToString();

                                {
                                    DirectoryInfo
                                    = new DirectoryInfo
                                    (Path);

                                    IReadOnlyCollection
                                    <FileInfo>
                                    IReadOnlyCollection
                                    = DirectoryInfo
                                    .GetFiles();

                                    for (int x = 0;
                                    x < IReadOnlyCollection
                                    .Count;
                                    x++)
                                    {
                                        FileInfo FileInfo
                                        = IReadOnlyCollection
                                        .ElementAt(x);

                                        DateTime DateTime
                                        = FileInfo
                                        .CreationTimeUtc;

                                        bool Boolean
                                        = DateTime
                                        > DateTime
                                        .UtcNow;

                                        switch (Boolean)
                                        {
                                            case true:
                                                {
                                                    FileInfo
                                                    .Delete(); 
                                                }
                                                break;
                                        }
                                    }
                                }
                            }
                        }
                    }
                }))
            };

            while (true)
            {
                int Length
                = List
                .Count;

                for (int i = 0; i < Length; i++)
                {
                    KeyValuePair
                    <KeyValuePair
                    <TimeSpan, DateTime>,
                    Action>
                    KeyValuePair
                    = List
                    .ElementAt(i);

                    TimeSpan TimeSpan
                    = KeyValuePair
                    .Key
                    .Key;

                    DateTime DateTime
                    = KeyValuePair
                    .Key
                    .Value;

                    bool Boolean
                    = DateTime
                    <= DateTime
                    .Now;

                    switch (Boolean)
                    {
                        case true:
                            {
                                DateTime
                                = DateTime.Now
                                .Add(TimeSpan);

                                Action Action
                                = KeyValuePair
                                .Value;

                                List[i]
                                = new KeyValuePair
                                <KeyValuePair
                                <TimeSpan, DateTime>,
                                Action>
                                (
                                    new KeyValuePair
                                    <TimeSpan, DateTime>(
                                    TimeSpan,
                                    DateTime),
                                    Action);

                                await Task
                                .Factory
                                .StartNew(
                                Action,
                                TaskCreationOptions
                                .None);
                            }
                            break;
                    }
                }

                await Task
                .Delay(
                TimeSpan
                .FromSeconds(2));
            }
        }
    }
